UPDATE programmes SET title_ru=REPLACE(title_ru,'[RU needs review] ',''),body_ru=REPLACE(body_ru,'[RU needs review] ',''),cta_label_ru=REPLACE(cta_label_ru,'[RU needs review] ','');
UPDATE speakers SET name_ru=REPLACE(name_ru,'[RU needs review] ',''),title_ru=REPLACE(title_ru,'[RU needs review] ',''),org_ru=REPLACE(org_ru,'[RU needs review] ',''),country_ru=REPLACE(country_ru,'[RU needs review] ',''),bio_ru=REPLACE(COALESCE(bio_ru,''),'[RU needs review] ','');
