UPDATE page_sections SET items_ru_json='["Искусственный интеллект","Кибербезопасность","Финтех","Блокчейн и криптовалюты","Облака и связь","5G и телеком","Образовательные технологии","Медицинские технологии","Умные города","Зелёные технологии"]' WHERE section_key='sectors';
UPDATE page_sections SET items_ru_json='[{"title":"ИИ и интеллектуальная инфраструктура","body":"От умного сельского хозяйства до экспорта ИИ — Казахстан ускоряет развитие технологий в Центральной Азии.","image":"https://www.gitexcac.com/images/AI_Img.jpg"},{"title":"Центры обработки данных","body":"Казахстан развивает цифровую инфраструктуру региона при поддержке прогрессивной политики.","image":"https://www.gitexcac.com/images/data_centers_img.jpg"},{"title":"Индустрия 4.0","body":"Автоматизация, IoT и цифровые двойники меняют производство и цепочки поставок.","image":"https://www.gitexcac.com/images/industry_img.jpg"},{"title":"Кибербезопасность","body":"Безопасная и адаптивная киберэкосистема защищает инфраструктуру и цифровое доверие.","image":"https://www.gitexcac.com/images/cybersecurity_img.jpg"},{"title":"Умная энергетика","body":"Чистая энергия и устойчивая инфраструктура ускоряют зелёный переход.","image":"https://www.gitexcac.com/images/smart_energy_img.jpg"},{"title":"Инвестиции и инновации","body":"Международный капитал превращает регион в платформу для инноваций.","image":"https://www.gitexcac.com/images/Investment_img.jpg"},{"title":"Финансы будущего и цифровые активы","body":"Связанная региональная экономика объединяет рынки разных континентов.","image":"https://www.gitexcac.com/images/future_finance_img.jpg"}]' WHERE section_key='tracks';
